def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos_from(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            a, b = value[0], value[1]
            if isinstance(a, int) and isinstance(b, int):
                return a, b
            try:
                return int(a), int(b)
            except Exception:
                return default
        return default

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_target(src, targets, prefer_far=False):
        best = None
        best_key = None
        for t in targets:
            p = pos_from(t, None)
            if p is None:
                continue
            d = dist(src, p)
            key = (-d, p[0], p[1]) if prefer_far else (d, p[0], p[1])
            if best is None or key < best_key:
                best = p
                best_key = key
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos_from(observation.get("self_position", observation.get("agent_position", (0, 0))))
    ox, oy = pos_from(observation.get("opponent_position", observation.get("enemy_position", (sx, sy))), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_target(opp_pos, corners, prefer_far=True) or (0, 0)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("neutral_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier")
            or []
        )
        target = best_target(self_pos, targets, prefer_far=False)
        if target is not None:
            return step_toward(self_pos, target)
        # Fallback: drift toward center or away from opponent if no territory info exists.
        cx, cy = (w // 2 if w else sx), (h // 2 if h else sy)
        if dist(self_pos, opp_pos) <= 2:
            return step_toward(self_pos, (sx * 2 - ox, sy * 2 - oy))
        return step_toward(self_pos, (cx, cy))

    resources = (
        observation.get("resources")
        or observation.get("resource_positions")
        or observation.get("food")
        or observation.get("targets")
        or []
    )
    target = best_target(self_pos, resources, prefer_far=False)
    if target is not None:
        return step_toward(self_pos, target)

    # Resource fallback: move toward opponent if it helps contest, else toward center.
    if w and h:
        center = (w // 2, h // 2)
        if dist(self_pos, opp_pos) <= 1:
            away = (sx * 2 - ox, sy * 2 - oy)
            return step_toward(self_pos, away)
        return step_toward(self_pos, center)

    return [0, 0]

